# -----------------------------
# Helper Function: Animated Gradient Progress Bar
# -----------------------------
def gradient_progress_bar(progress_pct, height_px=22):
    pct = max(0.0, min(progress_pct, 1.0)) * 100
    st.markdown(
        f"""
        <style>
        @keyframes gradientMove {{
            0% {{ background-position: 0% 50%; }}
            50% {{ background-position: 100% 50%; }}
            100% {{ background-position: 0% 50%; }}
        }}
        .gradient-progress-outer {{
            width: 100%;
            background-color: #e0e0e0;
            border-radius: 999px;
            padding: 3px;
            box-sizing: border-box;
            margin: 8px 0 16px 0;
        }}
        .gradient-progress-inner {{
            width: {pct}%;
            height: {height_px}px;
            border-radius: 999px;
            background: linear-gradient(90deg, #1e88e5, #43a047, #1e88e5, #43a047);
            background-size: 300% 300%;
            animation: gradientMove 4s ease infinite;
            transition: width 0.4s ease;
        }}
        </style>
        <div class="gradient-progress-outer">
            <div class="gradient-progress-inner"></div>
        </div>
        """,
        unsafe_allow_html=True
    )

# -----------------------------
# Helper Function: Correct, Animal-Specific Photo Lookup
# -----------------------------
FALLBACK_ANIMAL_PHOTO = "https://placehold.co/500x350?text=Photo+Unavailable"

@st.cache_data(ttl=60 * 60 * 24, show_spinner=False)
def get_animal_photo_url(animal_name: str) -> str:
    """
    Looks up the real photo for a SPECIFIC animal by querying Wikipedia's
    summary API using that exact animal's name, so the photo returned is
    always tied to the correct animal (never a random/generic image).

    Improvements over a plain exact-title lookup:
    - First tries Wikipedia's search (opensearch) API to resolve the best
      matching page title. This fixes cases where the exact animal name
      doesn't match a Wikipedia page title 1:1 (which previously showed
      "Photo Unavailable" for some animals).
    - Skips disambiguation pages, since their lead image isn't the animal.
    - Skips any image whose filename indicates it's a skull, skeleton,
      fossil, taxidermy mount, or museum specimen rather than a photo of
      the live animal (which previously caused some skull photos to show
      up instead of the actual animal).
    """
    headers = {"User-Agent": "AnimalAdvocatorsApp/1.0 (educational streamlit app)"}
    non_photo_keywords = [
        "skull", "skeleton", "fossil", "bone", "taxidermy", "specimen",
        "mount", "museum", "diagram", "drawing", "illustration", "map",
        "distribution", "range map", "cladogram", "anatomy",
    ]

    def is_usable_image(image_url):
        if not image_url:
            return False
        lower_url = image_url.lower()
        return not any(bad in lower_url for bad in non_photo_keywords)

    def get_page_photo(page_title, animal_terms):
        """Returns a suitable photo from the article's image gallery as a fallback."""
        image_list_params = {
            "action": "query",
            "titles": page_title,
            "prop": "images",
            "imlimit": 50,
            "format": "json",
        }
        image_list_response = requests.get(
            "https://en.wikipedia.org/w/api.php",
            params=image_list_params,
            headers=headers,
            timeout=5,
        )
        if image_list_response.status_code != 200:
            return None

        pages = image_list_response.json().get("query", {}).get("pages", {})
        image_titles = [
            image["title"]
            for page in pages.values()
            for image in page.get("images", [])
            if is_usable_image(image.get("title"))
        ]
        if not image_titles:
            return None

        def image_score(title):
            lower_title = title.lower()
            return sum(term in lower_title for term in animal_terms) + (".jpg" in lower_title or ".jpeg" in lower_title)

        image_titles.sort(key=image_score, reverse=True)
        image_info_params = {
            "action": "query",
            "titles": "|".join(image_titles[:20]),
            "prop": "imageinfo",
            "iiprop": "url",
            "iiurlwidth": 900,
            "format": "json",
        }
        image_info_response = requests.get(
            "https://en.wikipedia.org/w/api.php",
            params=image_info_params,
            headers=headers,
            timeout=5,
        )
        if image_info_response.status_code != 200:
            return None

        image_pages = image_info_response.json().get("query", {}).get("pages", {})
        image_urls = {
            page.get("title"): page.get("imageinfo", [{}])[0].get("thumburl") or page.get("imageinfo", [{}])[0].get("url")
            for page in image_pages.values()
        }
        for image_title in image_titles:
            image_url = image_urls.get(image_title)
            if is_usable_image(image_url):
                return image_url
        return None

    try:
        name = animal_name.strip()
        candidate_titles = [name]
        animal_terms = [term for term in name.lower().replace("-", " ").split() if len(term) > 2]

        # Use Wikipedia's search API to find the best-matching page title
        # in case the animal's exact name isn't an exact Wikipedia title.
        search_url = "https://en.wikipedia.org/w/api.php"
        search_params = {
            "action": "opensearch",
            "search": name,
            "limit": 3,
            "namespace": 0,
            "format": "json",
        }
        search_response = requests.get(search_url, params=search_params, headers=headers, timeout=5)
        if search_response.status_code == 200:
            search_data = search_response.json()
            if len(search_data) > 1 and search_data[1]:
                # Prefer search results, but keep the original name as a
                # fallback in case the search API returns nothing useful.
                candidate_titles.extend(search_data[1])

        for candidate in candidate_titles:
            page_title = candidate.strip().replace(" ", "_")
            url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{page_title}"
            response = requests.get(url, headers=headers, timeout=5)
            if response.status_code != 200:
                continue

            data = response.json()
            if data.get("type") == "disambiguation":
                continue

            thumbnail = data.get("thumbnail", {}).get("source")
            original = data.get("originalimage", {}).get("source")

            if is_usable_image(thumbnail):
                return thumbnail
            if is_usable_image(original):
                return original

            try:
                gallery_photo = get_page_photo(candidate, animal_terms)
            except Exception:
                gallery_photo = None
            if gallery_photo:
                return gallery_photo

        return FALLBACK_ANIMAL_PHOTO
    except Exception:
        return FALLBACK_ANIMAL_PHOTO

